import { SQL, sql } from 'drizzle-orm';
import { AnyPgColumn, check, text, timestamp, uuid } from 'drizzle-orm/pg-core';
import { v7 as uuidv7 } from 'uuid';

/**
 * Column builders for the conventions every table follows (see the library README).
 * Columns are declared unnamed in camelCase; the `snake_case` casing names them in SQL.
 */

/**
 * UUIDv7 primary key, generated by the API: time-ordered, so new rows land at the end of the index.
 * Postgres 17 has no `uuidv7()`, hence no database default.
 */
export const primaryId = () =>
  uuid()
    .primaryKey()
    .$defaultFn(() => uuidv7());

/**
 * `created_at` and `updated_at` for a main table, both from the database clock.
 * `updated_at` moves forward whenever Drizzle updates the row.
 */
export const timestamps = () => ({
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate((): SQL => sql`now()`),
});

/**
 * A text column holding one of `values`, typically a shared Zod enum's `.options`.
 * Pair it with {@link enumCheck} so the database refuses anything else.
 */
export const textEnum = <const T extends string>(values: readonly T[]) =>
  // `enum` only types the column; the database side is enforced by `enumCheck`.
  text({ enum: values as [T, ...T[]] });

/**
 * CHECK constraint keeping `column` within `values`. Name it `<table>_<column>_check`.
 * Changing `values` changes the constraint, so `drizzle-kit generate` emits a migration for it.
 */
export const enumCheck = (name: string, column: AnyPgColumn, values: readonly string[]) => {
  if (values.length === 0) throw new Error(`enumCheck ${name}: no allowed values`);
  return check(
    name,
    sql`${column} IN (${sql.join(
      values.map((value) => sql.raw(`'${value.replaceAll("'", "''")}'`)),
      sql`, `,
    )})`,
  );
};
